    logic                                  mon_arb_monbus_valid_in     [9];
    logic                                  mon_arb_monbus_ready_in     [9];
    ocelus_common_pkg::monitor_packet_t   mon_arb_monbus_packet_in    [9];
    ocelus_common_pkg::monbus_timestamp_t mon_arb_monbus_timestamp_in [9];
    assign mon_arb_monbus_valid_in[0]     = monbus_cpu_0_wr_valid;
    assign monbus_cpu_0_wr_ready = mon_arb_monbus_ready_in[0];
    assign mon_arb_monbus_packet_in[0]    = monbus_cpu_0_wr_packet;
    assign mon_arb_monbus_timestamp_in[0] = monbus_cpu_0_wr_timestamp;
    assign mon_arb_monbus_valid_in[1]     = monbus_cpu_0_rd_valid;
    assign monbus_cpu_0_rd_ready = mon_arb_monbus_ready_in[1];
    assign mon_arb_monbus_packet_in[1]    = monbus_cpu_0_rd_packet;
    assign mon_arb_monbus_timestamp_in[1] = monbus_cpu_0_rd_timestamp;
    assign mon_arb_monbus_valid_in[2]     = monbus_dma_1_wr_valid;
    assign monbus_dma_1_wr_ready = mon_arb_monbus_ready_in[2];
    assign mon_arb_monbus_packet_in[2]    = monbus_dma_1_wr_packet;
    assign mon_arb_monbus_timestamp_in[2] = monbus_dma_1_wr_timestamp;
    assign mon_arb_monbus_valid_in[3]     = monbus_dma_1_rd_valid;
    assign monbus_dma_1_rd_ready = mon_arb_monbus_ready_in[3];
    assign mon_arb_monbus_packet_in[3]    = monbus_dma_1_rd_packet;
    assign mon_arb_monbus_timestamp_in[3] = monbus_dma_1_rd_timestamp;
    assign mon_arb_monbus_valid_in[4]     = monbus_lfsr_2_rd_valid;
    assign monbus_lfsr_2_rd_ready = mon_arb_monbus_ready_in[4];
    assign mon_arb_monbus_packet_in[4]    = monbus_lfsr_2_rd_packet;
    assign mon_arb_monbus_timestamp_in[4] = monbus_lfsr_2_rd_timestamp;
    assign mon_arb_monbus_valid_in[5]     = monbus_ddr_0_wr_valid;
    assign monbus_ddr_0_wr_ready = mon_arb_monbus_ready_in[5];
    assign mon_arb_monbus_packet_in[5]    = monbus_ddr_0_wr_packet;
    assign mon_arb_monbus_timestamp_in[5] = monbus_ddr_0_wr_timestamp;
    assign mon_arb_monbus_valid_in[6]     = monbus_ddr_0_rd_valid;
    assign monbus_ddr_0_rd_ready = mon_arb_monbus_ready_in[6];
    assign mon_arb_monbus_packet_in[6]    = monbus_ddr_0_rd_packet;
    assign mon_arb_monbus_timestamp_in[6] = monbus_ddr_0_rd_timestamp;
    assign mon_arb_monbus_valid_in[7]     = monbus_sram_1_wr_valid;
    assign monbus_sram_1_wr_ready = mon_arb_monbus_ready_in[7];
    assign mon_arb_monbus_packet_in[7]    = monbus_sram_1_wr_packet;
    assign mon_arb_monbus_timestamp_in[7] = monbus_sram_1_wr_timestamp;
    assign mon_arb_monbus_valid_in[8]     = monbus_sram_1_rd_valid;
    assign monbus_sram_1_rd_ready = mon_arb_monbus_ready_in[8];
    assign mon_arb_monbus_packet_in[8]    = monbus_sram_1_rd_packet;
    assign mon_arb_monbus_timestamp_in[8] = monbus_sram_1_rd_timestamp;

    monbus_arbiter #(
        .CLIENTS            (9),
        .INPUT_SKID_ENABLE  (1),
        .OUTPUT_SKID_ENABLE (1),
        .INPUT_SKID_DEPTH   (2),
        .OUTPUT_SKID_DEPTH  (2)
    ) u_mon_arbiter (
        .axi_aclk            (aclk),
        .axi_aresetn         (aresetn),
        .block_arb           (1'b0),
        .monbus_valid_in     (mon_arb_monbus_valid_in),
        .monbus_ready_in     (mon_arb_monbus_ready_in),
        .monbus_packet_in    (mon_arb_monbus_packet_in),
        .monbus_timestamp_in (mon_arb_monbus_timestamp_in),
        .monbus_valid        (mon_arb_monbus_valid),
        .monbus_ready        (mon_arb_monbus_ready),
        .monbus_packet       (mon_arb_monbus_packet),
        .monbus_timestamp    (mon_arb_monbus_timestamp),
        /* verilator lint_off PINCONNECTEMPTY */
        .grant_valid         (),
        .grant               (),
        .grant_id            (),
        .last_grant          ()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    monbus_axil4_axil4_group #(
        // FIFO_DEPTH_WRITE is in BEATS in the monbus group family;
        // the master-write burst fires on cfg_flush_watermark or timeout.
        .FIFO_DEPTH_ERR      (64),
        .FIFO_DEPTH_WRITE    (96),
        .ADDR_WIDTH          (32),
        .FLUSH_TIMEOUT_CYCLES(1024),
        .NUM_PROTOCOLS       (3),
        .USE_COMPRESSION     (0)
    ) u_mon_axil_group (
        .axi_aclk          (aclk),
        .axi_aresetn       (aresetn),
        // Arbiter output as the single monbus input + side-band timestamp
        .monbus_valid      (mon_arb_monbus_valid),
        .monbus_ready      (mon_arb_monbus_ready),
        .monbus_packet     (mon_arb_monbus_packet),
        .monbus_timestamp  (mon_arb_monbus_timestamp),
        // Free-running timestamp shared with every wrapper's i_mon_time
        .mon_time_out      (mon_time_w),
        // Slave-read port (axil4)
        .s_axil_arvalid (s_mon_axil_arvalid),
        .s_axil_arready (s_mon_axil_arready),
        .s_axil_araddr (s_mon_axil_araddr),
        .s_axil_arprot (s_mon_axil_arprot),
        .s_axil_rvalid (s_mon_axil_rvalid),
        .s_axil_rready (s_mon_axil_rready),
        .s_axil_rdata (s_mon_axil_rdata),
        .s_axil_rresp (s_mon_axil_rresp),
        // Master-write port (axil4)
        .m_axil_awvalid (m_mon_axil_awvalid),
        .m_axil_awready (m_mon_axil_awready),
        .m_axil_awaddr (m_mon_axil_awaddr),
        .m_axil_awprot (m_mon_axil_awprot),
        .m_axil_wvalid (m_mon_axil_wvalid),
        .m_axil_wready (m_mon_axil_wready),
        .m_axil_wdata (m_mon_axil_wdata),
        .m_axil_wstrb (m_mon_axil_wstrb),
        .m_axil_bvalid (m_mon_axil_bvalid),
        .m_axil_bready (m_mon_axil_bready),
        .m_axil_bresp (m_mon_axil_bresp),
        // CAM clear: tied inert, same as every timing wrapper's.
        // The group's cam_clear was simply never connected, leaving
        // a floating input with no port default on 13 variants.
        .cam_clear         (1'b0),
        // IRQ
        .irq_out           (mon_irq_out),
        // Group-level cfg
        .cfg_base_addr     (cfg_mon_group_base_addr),
        .cfg_limit_addr     (cfg_mon_group_limit_addr),
        .cfg_flush_watermark     (cfg_mon_group_flush_watermark),
        .cfg_axi_pkt_mask     (cfg_mon_group_axi_pkt_mask),
        .cfg_axi_err_select     (cfg_mon_group_axi_err_select),
        .cfg_axi_error_mask     (cfg_mon_group_axi_error_mask),
        .cfg_axi_timeout_mask     (cfg_mon_group_axi_timeout_mask),
        .cfg_axi_compl_mask     (cfg_mon_group_axi_compl_mask),
        .cfg_axi_thresh_mask     (cfg_mon_group_axi_thresh_mask),
        .cfg_axi_perf_mask     (cfg_mon_group_axi_perf_mask),
        .cfg_axi_addr_mask     (cfg_mon_group_axi_addr_mask),
        .cfg_axi_debug_mask     (cfg_mon_group_axi_debug_mask),
        .cfg_axis_pkt_mask     (cfg_mon_group_axis_pkt_mask),
        .cfg_axis_err_select     (cfg_mon_group_axis_err_select),
        .cfg_axis_error_mask     (cfg_mon_group_axis_error_mask),
        .cfg_axis_timeout_mask     (cfg_mon_group_axis_timeout_mask),
        .cfg_axis_compl_mask     (cfg_mon_group_axis_compl_mask),
        .cfg_axis_credit_mask     (cfg_mon_group_axis_credit_mask),
        .cfg_axis_channel_mask     (cfg_mon_group_axis_channel_mask),
        .cfg_axis_stream_mask     (cfg_mon_group_axis_stream_mask),
        .cfg_core_pkt_mask     (cfg_mon_group_core_pkt_mask),
        .cfg_core_err_select     (cfg_mon_group_core_err_select),
        .cfg_core_error_mask     (cfg_mon_group_core_error_mask),
        .cfg_core_timeout_mask     (cfg_mon_group_core_timeout_mask),
        .cfg_core_compl_mask     (cfg_mon_group_core_compl_mask),
        .cfg_core_thresh_mask     (cfg_mon_group_core_thresh_mask),
        .cfg_core_perf_mask     (cfg_mon_group_core_perf_mask),
        .cfg_core_debug_mask     (cfg_mon_group_core_debug_mask),
        .cfg_compress_en     (cfg_mon_group_compress_en),
        /* verilator lint_off PINCONNECTEMPTY */
        .err_fifo_full     (),
        .write_fifo_full   (),
        .err_fifo_count    (),
        .write_fifo_count  (),
        .mon_compressor_stat_tier1_a        (),
        .mon_compressor_stat_tier1_b        (),
        .mon_compressor_stat_tier1_c        (),
        .mon_compressor_stat_tier0          (),
        .mon_compressor_stat_cam_miss       (),
        .mon_compressor_stat_delta_ts_ovf   (),
        .mon_compressor_stat_event_data_ovf (),
        .mon_compressor_stat_ed_delta_ovf   ()
        /* verilator lint_on PINCONNECTEMPTY */
    );

endmodule : bridge_3x2_rw_mcdc_mon
